#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAXN 100005

typedef struct {
    int idx;
    long long time;
} Event;

Event heap[MAXN];
int heap_size = 0;

void swap(Event *a, Event *b) {
    Event temp = *a;
    *a = *b;
    *b = temp;
}

void push(Event e) {
    int i = heap_size++;
    heap[i] = e;
    while (i > 0 && heap[(i - 1) / 2].time > heap[i].time) {
        swap(&heap[(i - 1) / 2], &heap[i]);
        i = (i - 1) / 2;
    }
}

Event pop() {
    Event res = heap[0];
    heap[0] = heap[--heap_size];
    int i = 0;
    while (1) {
        int smallest = i;
        int left = 2 * i + 1;
        int right = 2 * i + 2;
        if (left < heap_size && heap[left].time < heap[smallest].time)
            smallest = left;
        if (right < heap_size && heap[right].time < heap[smallest].time)
            smallest = right;
        if (smallest != i) {
            swap(&heap[i], &heap[smallest]);
            i = smallest;
        } else {
            break;
        }
    }
    return res;
}

int N, L;
