int is_local_max(int i) {
    int left_len = (i > 1 && !broken[i - 1]) ? a[i - 1] : 0;
    int right_len = (i < N && !broken[i + 1]) ? a[i + 1] : 0;
    return (a[i] > left_len && a[i] > right_len);
}

int main() {
