    memset(broken, 0, sizeof(broken));
    heap_size = 0;

    // push initially growing icicles
    for (int i = 1; i <= N; i++) {
        if (is_local_max(i)) {
            long long t = (long long)(L - a[i]);
            push((Event){i, t});
            break_time[i] = t;
        } else {
            break_time[i] = LLONG_MAX;
        }
    }

    long long current_time = 0;
