typedef long long ll;

typedef struct {
    int idx;
    ll t;
} HeapNode;

typedef struct {
    HeapNode *a;
    int sz, cap;
} MinHeap;

static void heap_init(MinHeap *h, int cap) {
    h->a = (HeapNode*)malloc(sizeof(HeapNode) * (cap + 5));
    h->sz = 0;
    h->cap = cap + 5;
}

static void heap_push(MinHeap *h, int idx, ll t) {
    int i = ++h->sz;
    while (i > 1 && h->a[i/2].t > t) {
        h->a[i] = h->a[i/2];
        i /= 2;
    }
    h->a[i].idx = idx;
    h->a[i].t = t;
}

static HeapNode heap_pop(MinHeap *h) {
    HeapNode ret = h->a[1];
    HeapNode last = h->a[h->sz--];
    int i = 1;
    while (i * 2 <= h->sz) {
        int c = i * 2;
        if (c + 1 <= h->sz && h->a[c + 1].t < h->a[c].t) c++;
        if (h->a[c].t >= last.t) break;
        h->a[i] = h->a[c];
        i = c;
    }
    h->a[i] = last;
    return ret;
}

static int heap_empty(MinHeap *h) {
    return h->sz == 0;
}

