public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new FileReader("input.txt"));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int L = Integer.parseInt(st.nextToken());

        int[] a = new int[N + 2];
        for (int i = 1; i <= N; i++) {
            a[i] = Integer.parseInt(br.readLine());
        }
        br.close();

        // time[i] = break time for icicle i, initially INF
        long[] breakTime = new long[N + 2];
        Arrays.fill(breakTime, Long.MAX_VALUE);
        boolean[] broken = new boolean[N + 2];
        broken[0] = broken[N + 1] = true;

        // Priority queue: (time, index)
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(o -> o[0]));

        // Initial break time calculation
        for (int i = 1; i <= N; i++) {
            long time = computeBreakTime(i, a, L, N);
            if (time != Long.MAX_VALUE) {
                breakTime[i] = time;
                pq.offer(new long[]{time, i});
            }
        }

        long currentTime = 0;
        while (!pq.isEmpty()) {
            long[] top = pq.poll();
            long t = top[0];
            int idx = (int) top[1];
            if (broken[idx] || t != breakTime[idx]) continue;

            currentTime = t;
            broken[idx] = true;
            a[idx] = 0;

            // Check left neighbor
            int left = idx - 1;
            if (left >= 1 && !broken[left]) {
                long newTime = computeBreakTime(left, a, L, N);
                if (newTime < breakTime[left]) {
                    breakTime[left] = newTime;
                    pq.offer(new long[]{newTime, left});
                }
            }
            // Check right neighbor
            int right = idx + 1;
            if (right <= N && !broken[right]) {
                long newTime = computeBreakTime(right, a, L, N);
                if (newTime < breakTime[right]) {
                    breakTime[right] = newTime;
                    pq.offer(new long[]{newTime, right});
                }
            }
        }

        PrintWriter pw = new PrintWriter(new FileWriter("output.txt"));
        pw.println(currentTime);
        pw.close();
    }

    static long computeBreakTime(int i, int[] a, int L, int N) {
        if (a[i] == 0) return Long.MAX_VALUE;
        boolean canGrow;
        if (i == 1) {
            canGrow = a[1] > a[2];
        } else if (i == N) {
            canGrow = a[N] > a[N - 1];
        } else {
            canGrow = a[i] > a[i - 1] && a[i] > a[i + 1];
        }
        if (!canGrow) return Long.MAX_VALUE;
        return (long)(L - a[i]);
    }
}

