        while (true) {
            boolean[] isMax = new boolean[N];
            int maxCount = 0;
            for (int i = 0; i < N; i++) {
                if (a[i] == 0) continue;
                boolean leftOk = (i == 0) || (a[i] > a[i-1]);
                boolean rightOk = (i == N-1) || (a[i] > a[i+1]);
                if (leftOk && rightOk) { isMax[i] = true; maxCount++; }
            }
            if (maxCount == 0) break;
            long minSteps = Long.MAX_VALUE;
            for (int i = 0; i < N; i++) {
                if (isMax[i]) minSteps = Math.min(minSteps, L - a[i]);
            }
            time += minSteps;
            for (int i = 0; i < N; i++) {
                if (isMax[i]) { a[i] += minSteps; if (a[i] >= L) a[i] = 0; }
            }
        }
        System.out.println(time);
    }
}

