public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Node {
        int idx;
        long time;
        Node(int idx, long time) {
            this.idx = idx;
            this.time = time;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int L = fs.nextInt();

        int[] a = new int[N + 2];
        for (int i = 1; i <= N; i++) a[i] = fs.nextInt();

        int[] left = new int[N + 2];
        int[] right = new int[N + 2];
        boolean[] alive = new boolean[N + 2];
        long[] breakTime = new long[N + 2];
        Arrays.fill(breakTime, -1);

        for (int i = 1; i <= N; i++) {
            left[i] = i - 1;
            right[i] = i + 1;
            alive[i] = true;
        }
        right[N] = 0;

        PriorityQueue<Node> pq = new PriorityQueue<>(Comparator.comparingLong(o -> o.time));

        for (int i = 1; i <= N; i++) {
            if (isPeak(i, a, left, right, alive)) {
                pq.add(new Node(i, L - a[i]));
            }
        }

        long answer = 0;
        int broken = 0;

        while (broken < N) {
            Node cur = pq.poll();
            int i = cur.idx;
            long t = cur.time;

            if (!alive[i]) continue;
            if (breakTime[i] != -1) continue;
            if (!isPeak(i, a, left, right, alive)) continue;

            long expected = L - a[i];
            if (t != expected) continue;

            breakTime[i] = t;
            answer = Math.max(answer, t);
            alive[i] = false;
            broken++;

            int l = left[i];
            int r = right[i];

            if (l != 0) right[l] = r;
            if (r != 0) left[r] = l;

            if (l != 0 && alive[l] && isPeak(l, a, left, right, alive)) {
                pq.add(new Node(l, t + (L - a[l])));
            }
            if (r != 0 && alive[r] && isPeak(r, a, left, right, alive)) {
                pq.add(new Node(r, t + (L - a[r])));
            }
        }

        System.out.println(answer);
    }

    static boolean isPeak(int i, int[] a, int[] left, int[] right, boolean[] alive) {
        if (!alive[i]) return false;
        int l = left[i];
        int r = right[i];
        if (l == 0 && r == 0) return true;
        if (l == 0) return a[i] > a[r];
        if (r == 0) return a[i] > a[l];
        return a[i] > a[l] && a[i] > a[r];
    }
}

