int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, L;
    cin >> N >> L;
    vector<int> a(N);
    for (int i = 0; i < N; i++) cin >> a[i];

    // growth_start_time[i] = time when icicle i starts growing
    vector<long long> growth_start(N, -1);
    vector<long long> len(N);
    for (int i = 0; i < N; i++) len[i] = a[i];

    // priority queue: (break_time, index)
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;

    auto get_start_time = [&](int i) -> long long {
        // returns time when icicle i becomes longer than neighbors and starts growing
        if (len[i] == 0) return LLONG_MAX;
        long long left_len = (i > 0) ? len[i-1] : -1;
        long long right_len = (i < N-1) ? len[i+1] : -1;

        if (left_len != -1 && len[i] <= left_len) {
            // need to wait until left neighbor becomes shorter than len[i]
            // left neighbor length decreases only when it breaks (to 0)
            // We'll handle this case by checking neighbors on break events
            return LLONG_MAX;
        }
        if (right_len != -1 && len[i] <= right_len) {
            return LLONG_MAX;
        }
        // already longer than neighbors, starts now
        return 0;
    };

    auto schedule = [&](int i, long long current_time) {
        if (len[i] == 0) return;
        // Check if i should be growing now
        long long left_len = (i > 0) ? len[i-1] : -1;
        long long right_len = (i < N-1) ? len[i+1] : -1;

        bool can_grow = true;
        if (left_len != -1 && len[i] <= left_len) can_grow = false;
        if (right_len != -1 && len[i] <= right_len) can_grow = false;

        if (!can_grow) {
            growth_start[i] = -1;
            return;
        }

        if (growth_start[i] == -1) {
            growth_start[i] = current_time;
        }

        long long break_time = growth_start[i] + (L - len[i]);
        pq.push({break_time, i});
    };

    // Initialize
    for (int i = 0; i < N; i++) {
        schedule(i, 0);
    }

    long long current_time = 0;
    while (!pq.empty()) {
        auto [bt, i] = pq.top(); pq.pop();
        if (len[i] == 0) continue; // already broken

        // Recompute break_time in case it changed
        if (growth_start[i] == -1) continue;
        long long expected_break = growth_start[i] + (L - len[i]);
        if (expected_break != bt) continue; // stale event

        current_time = bt;
        // break icicle i
        len[i] = 0;
        growth_start[i] = -1;

        // Update neighbors
        if (i > 0) schedule(i-1, current_time);
        if (i < N-1) schedule(i+1, current_time);
    }

    cout << current_time << "\n";
    return 0;
}

