using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, L;
    cin >> N >> L;
    vector<int> a(N + 2, 0);
    for (int i = 1; i <= N; ++i) cin >> a[i];

    // dp[i] = time when icicle i breaks.
    // At any time before breaking, an icicle grows iff it is a local maximum
    // among currently unbroken neighbors.
    //
    // Key observation:
    // Let T[i] be the break time of i.
    // Icicle i can start/continue growing only after all neighbors that are
    // initially higher than it on each side have disappeared.
    //
    // Define:
    //   leftGreater[i]  = nearest j < i with a[j] > a[i], or 0 if none
    //   rightGreater[i] = nearest j > i with a[j] > a[i], or N+1 if none
    //
    // Then i becomes a local maximum exactly after both blocking greater
    // neighbors (if they exist) have broken, i.e. at time
    //   s[i] = max(T[leftGreater[i]], T[rightGreater[i]])
    // with T[0] = T[N+1] = 0.
    //
    // After time s[i], icicle i grows continuously until reaching L,
    // so
    //   T[i] = s[i] + (L - a[i]).
    //
    // Since blockers are strictly higher, processing in decreasing a[i]
    // order allows DP computation.

    vector<int> leftGreater(N + 2), rightGreater(N + 2);

    // nearest greater on the left
    {
        vector<int> st;
        for (int i = 1; i <= N; ++i) {
            while (!st.empty() && a[st.back()] < a[i]) st.pop_back();
            leftGreater[i] = st.empty() ? 0 : st.back();
            st.push_back(i);
        }
    }

    // nearest greater on the right
    {
        vector<int> st;
        for (int i = N; i >= 1; --i) {
            while (!st.empty() && a[st.back()] < a[i]) st.pop_back();
            rightGreater[i] = st.empty() ? (N + 1) : st.back();
            st.push_back(i);
        }
    }

    vector<ll> T(N + 2, 0);

    vector<int> ord(N);
    iota(ord.begin(), ord.end(), 1);
    sort(ord.begin(), ord.end(), [&](int x, int y) {
        return a[x] > a[y];
    });

    for (int i : ord) {
        ll s = max(T[leftGreater[i]], T[rightGreater[i]]);
        T[i] = s + (L - a[i]);
    }

    ll ans = 0;
    for (int i = 1; i <= N; ++i) ans = max(ans, T[i]);
    cout << ans << '\n';
    return 0;
}
